import { useVanillaStore } from "../lib/use-vanilla-store";
import { appStore } from "../state/app-store";
import { REGISTRY, REGISTRY_SPECIMENS, REGISTRY_SOURCES } from "../content";
import { usePersistence } from "../persistence/PersistenceProvider";
import type { ReduceMotionPreference, ThemePreference } from "@cas/persistence";

export function AboutPage() {
  const theme = useVanillaStore(appStore, (s) => s.settings.theme);
  const reduceMotion = useVanillaStore(appStore, (s) => s.settings.reduceMotion);
  const autoRotate = useVanillaStore(appStore, (s) => s.settings.autoRotate);
  const persistence = usePersistence();
  const assets = REGISTRY.assets;
  const draftCount = REGISTRY_SPECIMENS.filter(
    (specimen) => specimen.contentReview.status !== "approved",
  ).length;
  const totalFacts = REGISTRY_SPECIMENS.reduce(
    (sum, specimen) =>
      sum + specimen.structures.reduce((inner, structure) => inner + structure.facts.length, 0),
    0,
  );
  const highImpactFacts = REGISTRY_SPECIMENS.flatMap((specimen) =>
    specimen.structures.flatMap((structure) =>
      structure.facts.filter((fact) => fact.highImpact).map((fact) => ({ specimen, fact })),
    ),
  );
  const secondReviewed = highImpactFacts.filter(
    (entry) => entry.fact.secondReview?.status === "approved" && entry.fact.secondReview.reviewedAt,
  ).length;
  const releaseOpen = draftCount === 0 && secondReviewed === highImpactFacts.length;

  return (
    <div className="page page--about">
      <header className="page-header">
        <div>
          <p className="eyebrow">About this studio</p>
          <h1>Citations first, graphics second</h1>
          <p className="lede">
            Cell Architecture Studio is a local-first, accessible teaching gallery. Every specimen
            is a schematic, every fact carries a source locator, and the 3D viewer can always be
            replaced by text without losing the lesson.
          </p>
        </div>
        <div className="page-header__controls">
          <span className={`pill ${draftCount > 0 ? "pill--warn" : ""}`}>
            {draftCount > 0 ? `${draftCount} draft biology reviews` : "Biology reviews approved"}
          </span>
          <span className="pill">Release gate: {releaseOpen ? "open" : "closed"}</span>
        </div>
      </header>

      <div className="about-grid">
        <section className="panel" aria-labelledby="review-heading">
          <h2 id="review-heading">Review status</h2>
          <p>
            Draft content ships with visible labels. A release build fails while any biology review
            is unapproved or any high-impact claim lacks a second review.
          </p>
          <table className="compact-table">
            <caption className="visually-hidden">Biology review status by specimen</caption>
            <thead>
              <tr>
                <th scope="col">Specimen</th>
                <th scope="col">Status</th>
                <th scope="col">Reviewer</th>
                <th scope="col">Version</th>
              </tr>
            </thead>
            <tbody>
              {REGISTRY_SPECIMENS.map((specimen) => (
                <tr key={specimen.id}>
                  <th scope="row">{specimen.name}</th>
                  <td>
                    <span className="badge badge--draft">
                      <span className="status-dot status-dot--warn" aria-hidden="true" />
                      {specimen.contentReview.status}
                    </span>
                  </td>
                  <td>{specimen.contentReview.reviewer}</td>
                  <td>{specimen.contentVersion}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <p className="muted small">
            {highImpactFacts.length} high-impact claims are flagged; {secondReviewed} have a
            recorded second review. Release also requires an approved biology reviewer and date for
            every specimen. Review workflow: <code>docs/BIOLOGY-REVIEW.md</code>.
          </p>
        </section>

        <section className="panel" aria-labelledby="license-heading">
          <h2 id="license-heading">Provenance &amp; licensing</h2>
          <p>
            All shipped geometry is authored in this repository and licensed CC BY 4.0. The asset
            pipeline regenerates previews from the same instances the viewer builds, so a preview
            cannot show a part that the model lacks.
          </p>
          <table className="compact-table">
            <caption className="visually-hidden">Asset licences and attributions</caption>
            <thead>
              <tr>
                <th scope="col">Asset</th>
                <th scope="col">Licence</th>
                <th scope="col">Rights</th>
              </tr>
            </thead>
            <tbody>
              {assets.map((asset) => (
                <tr key={asset.id}>
                  <th scope="row">{asset.id.replace("asset-", "").replaceAll("-", " ")}</th>
                  <td>
                    <a href={asset.license.url} target="_blank" rel="noreferrer noopener">
                      {asset.license.name}
                    </a>
                  </td>
                  <td>
                    <span className="status-label">
                      <span
                        className={`status-dot ${asset.rightsReview.status === "approved" ? "status-dot--ok" : "status-dot--warn"}`}
                        aria-hidden="true"
                      />
                      {asset.rightsReview.status}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <details>
            <summary>Full attributions</summary>
            <ul className="attribution-list">
              {assets.map((asset) => (
                <li key={asset.id}>{asset.attribution}</li>
              ))}
            </ul>
          </details>
        </section>

        <section className="panel" id="sources" aria-labelledby="sources-heading">
          <h2 id="sources-heading">Sources</h2>
          <p>
            {REGISTRY_SOURCES.length} sources support {totalFacts} cited statements. Links open the
            publisher; locators name the chapter or section used.
          </p>
          <details>
            <summary>Show source catalogue</summary>
            <ul className="source-list">
              {REGISTRY_SOURCES.map((source) => (
                <li key={source.id}>
                  <a href={source.url} target="_blank" rel="noreferrer noopener">
                    {source.title}
                  </a>
                  <span className="muted small">
                    {source.publisher} · {source.edition} · accessed {source.accessedAt}
                  </span>
                </li>
              ))}
            </ul>
          </details>
        </section>

        <section className="panel" aria-labelledby="accessibility-heading">
          <h2 id="accessibility-heading">Accessibility</h2>
          <ul className="check-list">
            <li>Every control is reachable by keyboard, with visible focus and a skip link.</li>
            <li>
              The structure list repeats all model information; the canvas is decorative to
              assistive technology.
            </li>
            <li>
              Reduced-motion preferences disable auto-rotation and shorten camera transitions.
            </li>
            <li>Without WebGL, the static SVG preview and full text remain available.</li>
            <li>
              Layouts are tested at 320 CSS pixels, and quizzes do not require dragging or hovering.
            </li>
            <li>
              Colour is never the only signal: labels, text feedback, and pressed states carry
              meaning.
            </li>
          </ul>
        </section>

        <section className="panel" aria-labelledby="privacy-heading">
          <h2 id="privacy-heading">Privacy</h2>
          <p>
            Learning is local. Progress, settings, and favourites live in this browser profile only.
            There is no account, analytics, or server sync in this build.
          </p>
          <p>
            The static study helper runs offline. A live tutor remains off until a reviewed provider
            is configured and you explicitly opt in; prompts are not persisted and are never
            included in exports.
          </p>
          <p className="callout">
            Browser storage is not encrypted. Export or delete your data below before using a shared
            device.
          </p>
        </section>

        <section className="panel" aria-labelledby="data-heading">
          <h2 id="data-heading">Your data</h2>
          <p className="muted small">
            Storage mode: <strong>{persistence.adapterKind ?? "checking"}</strong>. Status:{" "}
            <strong>{persistence.status}</strong>.
          </p>
          <div className="button-row">
            <button
              type="button"
              className="button button--primary"
              onClick={() => void persistence.exportData()}
            >
              Export progress
            </button>
            <button
              type="button"
              className="button button--ghost"
              onClick={() => void persistence.requestPersistence()}
            >
              Request persistent storage
            </button>
            <button
              type="button"
              className="button button--danger"
              onClick={() => {
                if (
                  window.confirm(
                    "Delete local progress, favourites, and settings from this browser? This cannot be undone.",
                  )
                ) {
                  void persistence.deleteData();
                }
              }}
            >
              Delete local data
            </button>
          </div>
          <p className="muted small">
            Clearing site data in the browser has the same effect. Export first if you want a copy.
          </p>
        </section>

        <section className="panel panel--settings" aria-labelledby="settings-heading">
          <h2 id="settings-heading">Viewing &amp; motion</h2>
          <div className="settings-group">
            <label className="settings-row field">
              <span>Appearance</span>
              <select
                value={theme}
                onChange={(event) =>
                  appStore.getState().setTheme(event.target.value as ThemePreference)
                }
              >
                <option value="system">Follow system setting</option>
                <option value="light">Light</option>
                <option value="dark">Dark</option>
              </select>
            </label>
            <label className="settings-row field">
              <span>Motion preference</span>
              <select
                value={reduceMotion}
                onChange={(event) =>
                  appStore.getState().setReduceMotion(event.target.value as ReduceMotionPreference)
                }
              >
                <option value="system">Follow system setting</option>
                <option value="reduce">Reduce motion</option>
                <option value="no-preference">Allow motion</option>
              </select>
            </label>
            <label className="settings-row checkbox">
              <input
                type="checkbox"
                checked={autoRotate}
                onChange={(event) => appStore.getState().setAutoRotate(event.target.checked)}
              />
              <span>Auto-rotate 3D models by default (ignored when reduced motion is on)</span>
            </label>
          </div>
          <p className="muted small">
            Auto-rotation stops whenever you drag the model. The viewer also stops rotating when the
            tab is hidden.
          </p>
        </section>

        <section className="panel" aria-labelledby="limits-heading">
          <h2 id="limits-heading">Limits &amp; non-goals</h2>
          <ul className="check-list check-list--warn">
            <li>Not medical advice, diagnosis, or a substitute for a microscopy atlas.</li>
            <li>Models are schematic; organelle counts, colours, and spacing are illustrative.</li>
            <li>No accounts, classroom administration, analytics, or cloud sync in v1.</li>
            <li>
              Live tutoring is disabled by default and has no production provider in this build.
            </li>
          </ul>
          <p className="muted small">
            Build: registry {REGISTRY.version} · {REGISTRY_SPECIMENS.length} specimens ·{" "}
            {REGISTRY_SPECIMENS.reduce((total, specimen) => total + specimen.structures.length, 0)}{" "}
            structures.
          </p>
        </section>
      </div>
    </div>
  );
}
